/// Look up a punctuation's SyntaxKind
pub fn lookup_punct(s: &str) -> Option<SyntaxKind> {
    match s {
        "!==" => Some(SyntaxKind::BANG_EQ_EQ),
        "//*" => Some(SyntaxKind::PUNCT_2F2F2A),
        "::>" => Some(SyntaxKind::COLON_COLON_GT),
        ":>>" => Some(SyntaxKind::COLON_GT_GT),
        "===" => Some(SyntaxKind::EQ_EQ_EQ),
        "!=" => Some(SyntaxKind::BANG_EQ),
        "**" => Some(SyntaxKind::STAR_STAR),
        "*/" => Some(SyntaxKind::PUNCT_2A2F),
        "->" => Some(SyntaxKind::ARROW),
        ".." => Some(SyntaxKind::DOT_DOT),
        ".?" => Some(SyntaxKind::PUNCT_2E3F),
        "/*" => Some(SyntaxKind::PUNCT_2F2A),
        "//" => Some(SyntaxKind::PUNCT_2F2F),
        "::" => Some(SyntaxKind::COLON_COLON),
        ":=" => Some(SyntaxKind::COLON_EQ),
        ":>" => Some(SyntaxKind::COLON_GT),
        "<=" => Some(SyntaxKind::LT_EQ),
        "==" => Some(SyntaxKind::EQ_EQ),
        "=>" => Some(SyntaxKind::FAT_ARROW),
        ">=" => Some(SyntaxKind::GT_EQ),
        "??" => Some(SyntaxKind::QUESTION_QUESTION),
        "@@" => Some(SyntaxKind::AT_AT),
        "#" => Some(SyntaxKind::HASH),
        "$" => Some(SyntaxKind::DOLLAR),
        "%" => Some(SyntaxKind::PERCENT),
        "&" => Some(SyntaxKind::AMP),
        "(" => Some(SyntaxKind::L_PAREN),
        ")" => Some(SyntaxKind::R_PAREN),
        "*" => Some(SyntaxKind::STAR),
        "+" => Some(SyntaxKind::PLUS),
        "," => Some(SyntaxKind::COMMA),
        "-" => Some(SyntaxKind::MINUS),
        "." => Some(SyntaxKind::DOT),
        "/" => Some(SyntaxKind::SLASH),
        ":" => Some(SyntaxKind::COLON),
        ";" => Some(SyntaxKind::SEMICOLON),
        "<" => Some(SyntaxKind::LT),
        "=" => Some(SyntaxKind::EQ),
        ">" => Some(SyntaxKind::GT),
        "?" => Some(SyntaxKind::QUESTION),
        "@" => Some(SyntaxKind::AT),
        "[" => Some(SyntaxKind::L_BRACKET),
        "]" => Some(SyntaxKind::R_BRACKET),
        "^" => Some(SyntaxKind::CARET),
        "{" => Some(SyntaxKind::L_BRACE),
        "|" => Some(SyntaxKind::PIPE),
        "}" => Some(SyntaxKind::R_BRACE),
        "~" => Some(SyntaxKind::TILDE),
        _ => None,
    }
}
